#include "darc.h"
#include <stdlib.h>
#include <string.h>

static int need(size_t p,size_t n,size_t total){return p<=total && n<=total-p;}

int darc_file_serialize(const DarcFileObj *f,DarcBuf *b){
 darc_buf_init(b); uint64_t sum=0;
 if(darc_buf_u16(b,1)||darc_buf_u64(b,f->logical_size)||darc_buf_u64(b,(uint64_t)f->chunk_n)) goto bad;
 for(size_t i=0;i<f->chunk_n;i++){if(UINT64_MAX-sum<f->chunks[i].len)goto bad;sum+=f->chunks[i].len;if(darc_buf_put(b,f->chunks[i].cid.b,32)||darc_buf_u64(b,f->chunks[i].len))goto bad;}
 if(sum!=f->logical_size||darc_buf_put(b,f->digest,32)) goto bad;
 return 0;
bad:darc_buf_free(b);return -1;
}
int darc_file_parse(const uint8_t*p,size_t n,DarcFileObj*f){memset(f,0,sizeof* f);size_t o=0;if(!need(o,18,n)||darc_rd_u16(p)!=1)return -1;o=2;f->logical_size=darc_rd_u64(p+o);o+=8;uint64_t cn=darc_rd_u64(p+o);o+=8;if(cn>SIZE_MAX/sizeof(DarcChunkRef)||!need(o,(size_t)cn*40+32,n))return -1;f->chunks=darc_calloc((size_t)(cn?cn:1),sizeof* f->chunks);if(!f->chunks)return -1;f->chunk_n=(size_t)cn;uint64_t sum=0;for(size_t i=0;i<f->chunk_n;i++){memcpy(f->chunks[i].cid.b,p+o,32);o+=32;f->chunks[i].len=darc_rd_u64(p+o);o+=8;if(UINT64_MAX-sum<f->chunks[i].len)goto bad;sum+=f->chunks[i].len;}memcpy(f->digest,p+o,32);o+=32;if(o!=n||sum!=f->logical_size)goto bad;return 0;bad:darc_file_free(f);return -1;}
void darc_file_free(DarcFileObj*f){free(f->chunks);memset(f,0,sizeof*f);}

static int namecmp(const DarcTreeEnt*a,const DarcTreeEnt*b){size_t m=a->name_len<b->name_len?a->name_len:b->name_len;int c=memcmp(a->name,b->name,m);if(c)return c;return a->name_len<b->name_len?-1:a->name_len>b->name_len?1:0;}
static int entcmp_q(const void*a,const void*b){return namecmp((const DarcTreeEnt*)a,(const DarcTreeEnt*)b);}
int darc_tree_serialize(DarcTreeObj*t,DarcBuf*b){darc_buf_init(b);if(t->n>1)qsort(t->e,t->n,sizeof*t->e,entcmp_q);if(darc_buf_u16(b,1)||darc_buf_u64(b,(uint64_t)t->n))goto bad;for(size_t i=0;i<t->n;i++){DarcTreeEnt*e=&t->e[i];if(!e->name_len||memchr(e->name,'/',e->name_len)||memchr(e->name,0,e->name_len))goto bad;if(i&&namecmp(&t->e[i-1],e)>=0)goto bad;if(e->type<1||e->type>4)goto bad;if(darc_buf_bytestr(b,e->name,e->name_len)||darc_buf_u8(b,e->type)||darc_buf_u32(b,e->mode&07777u)||darc_buf_i64(b,e->mtime_ns))goto bad;if(e->type==1){if(darc_buf_put(b,e->cid.b,32)||darc_buf_u64(b,e->hardlink_group))goto bad;}else if(e->type==2){if(darc_buf_put(b,e->cid.b,32))goto bad;}else if(e->type==3){if(darc_buf_bytestr(b,e->target,e->target_len))goto bad;}else {if(darc_buf_bytestr(b,e->target,e->target_len)||darc_buf_u64(b,e->hardlink_group))goto bad;}}
 return 0;bad:darc_buf_free(b);return -1;}
int darc_tree_parse(const uint8_t*p,size_t n,DarcTreeObj*t){memset(t,0,sizeof*t);if(n<10||darc_rd_u16(p)!=1)return -1;size_t o=2;uint64_t cn=darc_rd_u64(p+o);o+=8;if(cn>SIZE_MAX/sizeof(DarcTreeEnt))return -1;t->e=darc_calloc((size_t)(cn?cn:1),sizeof*t->e);if(!t->e)return -1;t->n=(size_t)cn;for(size_t i=0;i<t->n;i++){DarcTreeEnt*e=&t->e[i];if(!need(o,8,n))goto bad;uint64_t ln=darc_rd_u64(p+o);o+=8;if(ln>SIZE_MAX||!need(o,(size_t)ln+13,n))goto bad;e->name=darc_malloc((size_t)ln? (size_t)ln:1);if(!e->name)goto bad;memcpy(e->name,p+o,(size_t)ln);e->name_len=(size_t)ln;o+=(size_t)ln;e->type=p[o++];e->mode=darc_rd_u32(p+o);o+=4;e->mtime_ns=darc_rd_i64(p+o);o+=8;if(!e->name_len||memchr(e->name,'/',e->name_len)||memchr(e->name,0,e->name_len)||e->type<1||e->type>4)goto bad;if(i&&namecmp(&t->e[i-1],e)>=0)goto bad;if(e->type==1){if(!need(o,40,n))goto bad;memcpy(e->cid.b,p+o,32);o+=32;e->hardlink_group=darc_rd_u64(p+o);o+=8;}else if(e->type==2){if(!need(o,32,n))goto bad;memcpy(e->cid.b,p+o,32);o+=32;}else {if(!need(o,8,n))goto bad;uint64_t tl=darc_rd_u64(p+o);o+=8;if(tl>SIZE_MAX||!need(o,(size_t)tl+(e->type==4?8:0),n))goto bad;e->target=darc_malloc((size_t)tl? (size_t)tl:1);if(!e->target)goto bad;memcpy(e->target,p+o,(size_t)tl);e->target_len=(size_t)tl;o+=(size_t)tl;if(e->type==4){e->hardlink_group=darc_rd_u64(p+o);o+=8;}}}if(o!=n)goto bad;return 0;bad:darc_tree_free(t);return -1;}
void darc_tree_free(DarcTreeObj*t){if(t->e)for(size_t i=0;i<t->n;i++){free(t->e[i].name);free(t->e[i].target);}free(t->e);memset(t,0,sizeof*t);}

int darc_snapshot_serialize(const DarcSnapshotObj*s,DarcBuf*b){darc_buf_init(b);if(darc_buf_u16(b,1)||darc_buf_i64(b,s->created_ns))goto bad;if(s->name){size_t n=strlen(s->name);if(!n||!darc_valid_utf8((const uint8_t*)s->name,n)||darc_buf_u8(b,1)||darc_buf_bytestr(b,s->name,n))goto bad;}else if(darc_buf_u8(b,0))goto bad;if(darc_buf_u8(b,s->has_parent?1:0))goto bad;if(s->has_parent&&darc_buf_put(b,s->parent.b,32))goto bad;if(darc_buf_put(b,s->root.b,32)||darc_buf_u32(b,s->root_mode)||darc_buf_i64(b,s->root_mtime_ns)||darc_buf_u64(b,(uint64_t)s->root_n))goto bad;for(size_t i=0;i<s->root_n;i++){size_t n=strlen(s->roots[i]);if(!darc_valid_utf8((const uint8_t*)s->roots[i],n)||darc_buf_bytestr(b,s->roots[i],n))goto bad;}if(darc_buf_put(b,s->profile_hash.b,32)||darc_buf_u64(b,s->logical_bytes)||darc_buf_u64(b,s->files)||darc_buf_u64(b,s->dirs)||darc_buf_u64(b,s->symlinks)||darc_buf_u64(b,s->hardlinks)||darc_buf_u64(b,s->unique_chunks)||darc_buf_u64(b,s->new_chunks)||darc_buf_u64(b,s->new_stored_bytes))goto bad;return 0;bad:darc_buf_free(b);return -1;}
int darc_snapshot_parse(const uint8_t*p,size_t n,DarcSnapshotObj*s){memset(s,0,sizeof*s);size_t o=0;if(!need(o,11,n)||darc_rd_u16(p)!=1)return -1;o=2;s->created_ns=darc_rd_i64(p+o);o+=8;uint8_t present=p[o++];if(present){if(!need(o,8,n))goto bad;uint64_t l=darc_rd_u64(p+o);o+=8;if(l>SIZE_MAX||!need(o,(size_t)l,n)||!darc_valid_utf8(p+o,(size_t)l))goto bad;s->name=darc_strndup((const char*)p+o,(size_t)l);if(!s->name)goto bad;o+=(size_t)l;}if(!need(o,1,n))goto bad;s->has_parent=p[o++]!=0;if(s->has_parent){if(!need(o,32,n))goto bad;memcpy(s->parent.b,p+o,32);o+=32;}if(!need(o,52,n))goto bad;memcpy(s->root.b,p+o,32);o+=32;s->root_mode=darc_rd_u32(p+o);o+=4;s->root_mtime_ns=darc_rd_i64(p+o);o+=8;uint64_t rn=darc_rd_u64(p+o);o+=8;if(rn>SIZE_MAX/sizeof(char*))goto bad;s->roots=darc_calloc((size_t)(rn?rn:1),sizeof(char*));if(!s->roots)goto bad;s->root_n=(size_t)rn;for(size_t i=0;i<s->root_n;i++){if(!need(o,8,n))goto bad;uint64_t l=darc_rd_u64(p+o);o+=8;if(l>SIZE_MAX||!need(o,(size_t)l,n)||!darc_valid_utf8(p+o,(size_t)l))goto bad;s->roots[i]=darc_strndup((const char*)p+o,(size_t)l);if(!s->roots[i])goto bad;o+=(size_t)l;}if(!need(o,96,n))goto bad;memcpy(s->profile_hash.b,p+o,32);o+=32;s->logical_bytes=darc_rd_u64(p+o);o+=8;s->files=darc_rd_u64(p+o);o+=8;s->dirs=darc_rd_u64(p+o);o+=8;s->symlinks=darc_rd_u64(p+o);o+=8;s->hardlinks=darc_rd_u64(p+o);o+=8;s->unique_chunks=darc_rd_u64(p+o);o+=8;s->new_chunks=darc_rd_u64(p+o);o+=8;s->new_stored_bytes=darc_rd_u64(p+o);o+=8;if(o!=n)goto bad;return 0;bad:darc_snapshot_free(s);return -1;}
void darc_snapshot_free(DarcSnapshotObj*s){free(s->name);if(s->roots)for(size_t i=0;i<s->root_n;i++)free(s->roots[i]);free(s->roots);memset(s,0,sizeof*s);}
